67	
68	  // Deep-link support: /blog/?lang=en or /blog/?lang=my
69	  var requested = new URLSearchParams(window.location.search).get('lang');
70	  if (requested === 'en' || requested === 'my') {
71	    applyFilter(requested);
72	  }
73	})();
